package io.lumine.mythic.lib.skill;
import io.lumine.mythic.lib.api.event.skill.*; import io.lumine.mythic.lib.api.player.MMOPlayerData; import io.lumine.mythic.lib.player.cooldown.CooldownObject; import io.lumine.mythic.lib.skill.handler.SkillHandler; import io.lumine.mythic.lib.skill.result.*; import io.lumine.mythic.lib.skill.result.def.SimpleSkillResult; import io.lumine.mythic.lib.skill.trigger.*; import java.util.*;
public abstract class Skill implements CooldownObject { private final SkillHandler<?> handler; private final TriggerType trigger; protected final Map<String,Double> modifiers=new HashMap<>(); public Skill(){this(TriggerType.CAST,null);} public Skill(TriggerType trigger){this(trigger,null);} public Skill(SkillHandler<?> handler){this(handler==null?TriggerType.CAST:handler.getDefaultTriggerType(),handler);} protected Skill(TriggerType trigger,SkillHandler<?> handler){this.trigger=trigger==null?TriggerType.CAST:trigger;this.handler=handler;} public SkillResult cast(MMOPlayerData data){return cast(new SkillMetadata(this,data));} public <T extends SkillResult> SkillResult cast(SkillMetadata metadata){boolean ok=getResult(metadata);SkillResult result=new SimpleSkillResult(ok);PlayerCastSkillEvent before=new PlayerCastSkillEvent(this,metadata,result);before.call();if(!before.isCancelled()&&result.isSuccessful(metadata))whenCast(metadata);new SkillCastEvent(this,metadata,result).call();return result;} public <T extends SkillResult> void castInstantly(SkillMetadata metadata,T result){PlayerCastSkillEvent before=new PlayerCastSkillEvent(this,metadata,result);before.call();if(!before.isCancelled()&&result.isSuccessful(metadata))whenCast(metadata);new SkillCastEvent(this,metadata,result).call();} public SkillResult cast(TriggerMetadata trigger){return cast(trigger.toSkillMetadata(this));} public SkillResult cast(MMOPlayerData data,TriggerType type){return cast(new TriggerMetadata(data,type));} public abstract boolean getResult(SkillMetadata metadata); public abstract void whenCast(SkillMetadata metadata); public SkillHandler<?> getHandler(){return handler;} public double getParameter(String id){return handler==null?0:handler.getDefaultItemParameter(id);} public String getCooldownPath(){return handler==null?getClass().getSimpleName():handler.getLowerCaseId();} public TriggerType getTrigger(){return trigger;} public double getModifier(String id){return modifiers.getOrDefault(id,0d);} @Override public String toString(){return getCooldownPath();} }
